package com.myaaptha.domain.finance;
import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.mock.web.MockMultipartFile;
class StatementDuplicateTest{
 @Test void smsOrManualMatchesAreSuggestionsRatherThanForcedDuplicateRemoval(){var repo=mock(FinancialTransactionRepository.class);var existing=new FinancialTransactionEntity();existing.setUserId(1L);existing.setAmount(new BigDecimal("100"));existing.setDirection("EXPENSE");existing.setSource("SMS");existing.setOccurredAt(Instant.parse("2026-02-01T05:30:00Z"));when(repo.findInMonth(eq(1L),any(),any())).thenReturn(List.of(existing));when(repo.findByUserIdAndSourceFingerprint(anyLong(),anyString())).thenReturn(Optional.empty());var api=new FinanceStatements(new StatementParser(),repo,new JdbcTemplate());var file=new MockMultipartFile("file","bank.csv","text/csv","Date,Description,Amount,Type\n01/02/2026,Grocery store,100,DR\n".getBytes(StandardCharsets.UTF_8));var row=api.preview(()->"1",file,"DMY","Asia/Kolkata","Savings").rows().getFirst();assertThat(row.possibleDuplicate()).isTrue();assertThat(row.duplicate()).isFalse();assertThat(row.issues()).isEmpty();}
 @Test void twoDigitYearsAndFormulaExportsAreHandledExplicitly(){assertThat(StatementParser.date("01/02/26","DMY",ZoneId.of("UTC"))).isEqualTo(Instant.parse("2026-02-01T00:00:00Z"));assertThat(FinanceStatements.quoted("=SUM(A1)\nmore")).startsWith("\"'=");}
}
